{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Human PET data for blonanserin show a brain/plasma ratio of 3.38 derived from D2 receptor occupancy, directly demonstrating good blood-brain barrier permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "PET imaging in cats shows high brain uptake of [11C]SA6298 in cortex, thalamus, striatum, and cerebellum, indicating effective BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "[11C]NE40 demonstrated high brain uptake and washout in mice, rhesus monkeys, and healthy humans, confirming robust BBB penetration across species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Coptisine was detected in mouse brain homogenates by LC-MS/MS, providing direct evidence of BBB crossing in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The NBPEA compound 34H-NBBr readily crossed the blood-brain barrier and reached detectable brain levels in zebrafish, supporting CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple direct in vivo BBB-penetration records across human, non-human primate, cat, mouse, and zebrafish consistently support meaningful CNS access. The favorable physicochemical prior further supports passive diffusion, and no contradictory experimental evidence is present.",
  "evidence_gaps": [
    "No direct experimental brain or CSF measurement for the query molecule itself.",
    "No brain tumor/glioma-specific pharmacokinetic or efflux-transporter data are available.",
    "Potential P-gp or BCRP liability was not directly tested in the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

